local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local UserInputService = game:GetService("UserInputService")
local player = Players.LocalPlayer
assert(game.PlaceId == 3623096087, "Wrong place for generated script package")
if type(_G.LycolesMuscleAutoTrainClose) == "function" then pcall(_G.LycolesMuscleAutoTrainClose) end

local timing = CONTRACT.timing or {}
local SETTINGS = {
    activationIntervalSeconds = tonumber(timing.activationIntervalSeconds) or 0.25,
    delayedOutcomeWindowSeconds = tonumber(timing.delayedOutcomeWindowSeconds) or 1.5,
    stallWindowSeconds = tonumber(timing.stallWindowSeconds) or 18.0,
    pollIntervalSeconds = tonumber(timing.pollIntervalSeconds) or 0.2,
    minActivationIntervalSeconds = tonumber(timing.minActivationIntervalSeconds) or 0.1,
    maxActivationIntervalSeconds = tonumber(timing.maxActivationIntervalSeconds) or 2.0,
}

local function clamp(value, minValue, maxValue)
    if value < minValue then return minValue end
    if value > maxValue then return maxValue end
    return value
end

local function round(value, digits)
    local p = 10 ^ (digits or 0)
    return math.floor(value * p + 0.5) / p
end

local function splitPath(path)
    local parts = {}
    for token in string.gmatch(path or "", "[^%.]+") do
        parts[#parts + 1] = token
    end
    return parts
end

local function resolvePath(path)
    if type(path) ~= "string" or path == "" then return nil, "empty path" end
    local parts = splitPath(path)
    if #parts == 0 then return nil, "invalid path" end

    local root = nil
    local index = 2
    if parts[1] == "LocalPlayer" then
        root = player
    elseif parts[1] == "Workspace" then
        root = workspace
    elseif parts[1] == "ReplicatedStorage" then
        root = game:GetService("ReplicatedStorage")
    elseif parts[1] == "Character" then
        root = player.Character
    elseif parts[1] == "Backpack" then
        root = player:FindFirstChild("Backpack")
    elseif player:FindFirstChild(parts[1]) then
        root = player
        index = 1
    else
        root = player:FindFirstChild("PlayerGui")
        index = 1
    end
    if not root then return nil, "missing root" end

    local current = root
    for i = index, #parts do
        current = current:FindFirstChild(parts[i])
        if not current then return nil, "missing segment: " .. tostring(parts[i]) end
    end
    return current, nil
end

local function readNumber(path)
    local obj = resolvePath(path)
    if not obj then return nil end

    if obj:IsA("ValueBase") then
        local ok, value = pcall(function() return obj.Value end)
        if ok then
            if type(value) == "number" then return value end
            if type(value) == "boolean" then return value and 1 or 0 end
        end
    end

    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
        local text = string.lower(string.gsub(obj.Text or "", "%s+", ""))
        local numeric = tonumber(text)
        if numeric ~= nil then return numeric end
        if text == "ready" or text == "claim" then return 1 end
        if text == "claimed" then return 0 end
        local mm, ss = string.match(text, "^(%d+):(%d+)$")
        if mm and ss then
            return (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0)
        end
        local hh, mm2, ss2 = string.match(text, "^(%d+):(%d+):(%d+)$")
        if hh and mm2 and ss2 then
            return (tonumber(hh) or 0) * 3600 + (tonumber(mm2) or 0) * 60 + (tonumber(ss2) or 0)
        end
    end

    if obj:IsA("GuiObject") then
        return obj.Visible and 1 or 0
    end

    return nil
end

local function resolveTool(toolPath, toolName)
    local exact = nil
    if type(toolPath) == "string" and toolPath ~= "" then
        exact = resolvePath(toolPath)
    end
    if exact and exact:IsA("Tool") then
        return exact
    end

    local candidates = {player:FindFirstChild("Backpack"), player.Character}
    for _, parent in ipairs(candidates) do
        if parent then
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("Tool") and child.Name == toolName then
                    return child
                end
            end
        end
    end
    return nil
end

local function activateGuiObject(obj)
    if not obj then return false, "nil object" end
    if not obj:IsA("GuiButton") then return false, "object is not GuiButton" end

    if type(firesignal) == "function" then
        local okClick = pcall(function()
            if obj.MouseButton1Click then
                firesignal(obj.MouseButton1Click)
            end
        end)
        if okClick then return true, "firesignal.MouseButton1Click" end

        local okActivated = pcall(function()
            if obj.Activated then
                firesignal(obj.Activated)
            end
        end)
        if okActivated then return true, "firesignal.Activated" end
    end

    local okActivate, activateErr = pcall(function() obj:Activate() end)
    if okActivate then
        return true, "GuiButton.Activate"
    end

    return false, "no-supported-gui-trigger: " .. tostring(activateErr)
end

local function scoreActionableGuiButton(button, contextKind)
    if not button or not button:IsA("GuiButton") then return -1e9 end
    local score = 0
    local low = string.lower(button.Name or "")
    if button.Visible then score += 10 else score -= 40 end
    if button.Active then score += 6 end
    if button.AutoButtonColor then score += 2 end
    if string.find(low, "claim", 1, true) or string.find(low, "collect", 1, true) then score += 12 end
    if string.find(low, "accept", 1, true) or string.find(low, "quest", 1, true) then score += 7 end
    if string.find(low, "button", 1, true) or string.find(low, "hitbox", 1, true) then score += 5 end
    if string.find(low, "label", 1, true) or string.find(low, "text", 1, true) then score -= 8 end
    if string.find(low, "close", 1, true) or string.find(low, "exit", 1, true) or string.find(low, "cancel", 1, true) then score -= 14 end
    if string.find(low, "skip", 1, true) then score -= 6 end
    if contextKind == "claim" and (string.find(low, "claim", 1, true) or string.find(low, "collect", 1, true)) then score += 10 end
    if contextKind == "open" and (string.find(low, "quest", 1, true) or string.find(low, "tab", 1, true) or string.find(low, "playtime", 1, true)) then score += 6 end
    return score
end

local function resolveActionableGuiButton(path, contextKind)
    local obj, err = resolvePath(path)
    if not obj then return nil, "resolve failed: " .. tostring(err) end

    if obj:IsA("GuiButton") then
        return obj, nil
    end

    local ancestor = obj
    for _ = 1, 6 do
        ancestor = ancestor and ancestor.Parent or nil
        if not ancestor then break end
        if ancestor:IsA("GuiButton") then
            return ancestor, nil
        end
    end

    local best = nil
    local bestScore = -1e9
    local searchRoot = obj
    if not searchRoot:IsA("GuiObject") and searchRoot.Parent and searchRoot.Parent:IsA("GuiObject") then
        searchRoot = searchRoot.Parent
    end
    if not searchRoot then
        return nil, "resolved object has no GUI ancestry"
    end

    local descendants = {}
    local okDesc = pcall(function()
        descendants = searchRoot:GetDescendants()
    end)
    if not okDesc then
        return nil, "descendant resolution failed"
    end

    for _, descendant in ipairs(descendants) do
        if descendant:IsA("GuiButton") then
            local score = scoreActionableGuiButton(descendant, contextKind)
            if score > bestScore then
                bestScore = score
                best = descendant
            end
        end
    end

    if best then
        return best, nil
    end

    return nil, "no actionable GuiButton resolved"
end

local function activateGuiPath(path, contextKind)
    local button, err = resolveActionableGuiButton(path, contextKind)
    if not button then return false, tostring(err) end
    return activateGuiObject(button)
end

local state = {
    alive = true,
    startClock = os.clock(),
    currentStrength = nil,
    initialStrength = nil,
    totalStrengthGain = 0,
    strengthGainPerMinute = 0,
    lastProgression = "none",
    stalled = false,
    intervalScale = 1.0,
    lastStatus = "ready",
    characterLifecycle = {
        respawnSuspended = false,
        suspensionReason = "ready",
        characterGeneration = 0,
        recoveryToken = 0,
        recoveryInProgress = false,
        lastRecoveryStartClock = nil,
        lastRecoveryDurationSeconds = 0,
        deathCount = 0,
        recoveryAttempts = 0,
        recoverySuccesses = 0,
        recoveryFailures = 0,
        recoveryTotalDurationSeconds = 0,
        lastFailureReason = nil,
        nextRecoveryAttemptAt = 0,
        missingToolRetryCount = 0,
        lastCharacterId = nil,
    },
}

local runtimeCapabilities = {
    firesignal = (type(firesignal) == "function"),
    setclipboard = (type(setclipboard) == "function" or type(toclipboard) == "function" or type(toClipboard) == "function"),
}

local features = {}
local featureOrder = {}
local rows = {}
local trainingMethodRows = {}
local statTargetRows = {}
local connections = {}
local characterConnections = {}

local function featureRuntime(definition, supported)
    local action = definition.action or {}
    return {
        id = tostring(definition.id or "feature"),
        title = tostring(definition.title or definition.id or "Feature"),
        supported = supported,
        includeInStartAll = definition.includeInStartAll == true,
        destructive = definition.destructive == true,
        definition = definition,
        action = action,
        attempts = 0,
        successes = 0,
        successfulCalls = 0,
        errors = 0,
        progressEvents = 0,
        progressTotal = 0,
        progressionByUnit = {},
        unresolvedPaths = {},
        lastProgress = "none",
        lastError = nil,
        outcomeState = supported and "action-invoked-outcome-unverified" or "unsupported-interaction",
        lastStatus = supported and "idle" or "unavailable",
        verifiedOutcomes = 0,
        unverifiedOutcomes = 0,
        blockedOutcomes = 0,
        unsupportedOutcomes = 0,
        runtimeFailureOutcomes = 0,
        lastInvokeAt = nil,
        pendingVerification = false,
        verifyEventSnapshot = 0,
        running = false,
        token = 0,
        cursor = 0,
        intervalSeconds = tonumber(action.intervalSeconds) or SETTINGS.activationIntervalSeconds,
        monitorValues = {},
        monitorPaths = {},
        trainingMethods = {},
        trainingMethodOrder = {},
        selectedTrainingMethodIds = {},
        trainingMethodStats = {},
        trainingMethodCursor = 0,
        lastTrainingMethodId = nil,
        pendingTrainingMethodId = nil,
        pendingTrainingMethodProgressSnapshot = 0,
        statTargets = {},
        statTargetOrder = {},
        activeStatTargets = {},
        methodStatMap = {},
        statRuntime = {},
        candidateCooldowns = {},
        monitorOnlyFallback = false,
        unresolvedActionableAttempts = 0,
    }
end

local featureDependencies = CONTRACT.featureDependencies or {}

for _, definition in ipairs(CONTRACT.featureContracts or {}) do
    local feature = featureRuntime(definition, definition.supported ~= false)
    local monitor = definition.monitor or {}
    if type(monitor.primaryOutcomePath) == "string" then
        feature.monitorPaths[#feature.monitorPaths + 1] = monitor.primaryOutcomePath
    end
    for _, path in ipairs(monitor.candidateStatePaths or {}) do
        if type(path) == "string" then
            feature.monitorPaths[#feature.monitorPaths + 1] = path
        end
    end
    for _, path in ipairs(monitor.questRepetitionStatePaths or {}) do
        if type(path) == "string" then
            feature.monitorPaths[#feature.monitorPaths + 1] = path
        end
    end

    if feature.action.kind == "tool_activate_selectable" then
        local defaults = {}
        for _, methodId in ipairs(feature.action.defaultSelectedMethodIds or {}) do
            if type(methodId) == "string" then
                defaults[methodId] = true
            end
        end
        for _, method in ipairs(feature.action.methods or {}) do
            if type(method) == "table" and type(method.id) == "string" then
                local methodId = method.id
                feature.trainingMethods[methodId] = method
                feature.trainingMethodOrder[#feature.trainingMethodOrder + 1] = methodId
                local fallbackDefault = (method.path == feature.action.primaryToolPath)
                local isSelected = defaults[methodId] == true or (defaults[methodId] == nil and fallbackDefault)
                feature.selectedTrainingMethodIds[methodId] = isSelected
                feature.trainingMethodStats[methodId] = {
                    attempts = 0,
                    successes = 0,
                    errors = 0,
                    progressEvents = 0,
                    progressionByUnit = {},
                    lastStatus = isSelected and "selected" or "not-selected",
                    unavailableUntil = 0,
                    lastError = nil,
                }
            end
        end

        for methodId, statIds in pairs(feature.action.methodStatMap or {}) do
            if type(methodId) == "string" and type(statIds) == "table" then
                feature.methodStatMap[methodId] = statIds
            end
        end

        for _, target in ipairs(feature.action.statTargets or {}) do
            if type(target) == "table" and type(target.id) == "string" then
                local targetId = target.id
                feature.statTargets[targetId] = target
                feature.statTargetOrder[#feature.statTargetOrder + 1] = targetId
                local isUnsupported = type(target.unsupportedReason) == "string" and target.unsupportedReason ~= ""
                feature.activeStatTargets[targetId] = (target.defaultActive ~= false) and not isUnsupported

                local runtimeTarget = {
                    selectedMethodIds = {},
                    currentValue = nil,
                    initialValue = nil,
                    totalGain = 0,
                    gainPerMinute = 0,
                    progressEvents = 0,
                    lastStatus = isUnsupported and "unsupported" or (target.defaultActive ~= false and "active" or "paused"),
                }

                local hasSelection = false
                for _, methodId in ipairs(target.defaultSelectedMethodIds or {}) do
                    if type(methodId) == "string" then
                        runtimeTarget.selectedMethodIds[methodId] = true
                        feature.selectedTrainingMethodIds[methodId] = true
                        hasSelection = true
                    end
                end

                if not hasSelection then
                    for _, methodRef in ipairs(target.methods or {}) do
                        if type(methodRef) == "table" and type(methodRef.methodId) == "string" then
                            runtimeTarget.selectedMethodIds[methodRef.methodId] = true
                            feature.selectedTrainingMethodIds[methodRef.methodId] = true
                            hasSelection = true
                            break
                        end
                    end
                end

                feature.statRuntime[targetId] = runtimeTarget
            end
        end

    end

    features[feature.id] = feature
    featureOrder[#featureOrder + 1] = feature
end

for _, unsupported in ipairs(CONTRACT.unsupportedFeatures or {}) do
    if features[unsupported.id] == nil then
        local definition = {
            id = unsupported.id,
            title = unsupported.title,
            includeInStartAll = false,
            destructive = false,
            action = {kind = "none"},
            evidence = unsupported.evidence,
        }
        local feature = featureRuntime(definition, false)
        features[feature.id] = feature
        featureOrder[#featureOrder + 1] = feature
    end
end

local globalStrengthPath = ((CONTRACT.outcomeModel or {}).primaryStatePath)

local function updateGlobalProgression()
    local value = readNumber(globalStrengthPath)
    local lifecycle = state.characterLifecycle
    if value ~= nil then
        if lifecycle.respawnSuspended or lifecycle.recoveryInProgress then
            state.currentStrength = value
            if state.initialStrength == nil then state.initialStrength = value end
        else
            if state.currentStrength ~= nil then
                local delta = value - state.currentStrength
                if delta > 0 then
                    state.totalStrengthGain += delta
                    state.lastProgression = string.format("+%s Strength", tostring(round(delta, 3)))
                elseif delta < 0 and math.abs(delta) >= math.max(25, math.abs(state.currentStrength) * 0.20) then
                    state.lastProgression = "strength baseline realigned after character lifecycle transition"
                end
            end
            state.currentStrength = value
            if state.initialStrength == nil then state.initialStrength = value end
        end
    end
    local elapsed = math.max(0.01, os.clock() - state.startClock)
    state.strengthGainPerMinute = (state.totalStrengthGain / elapsed) * 60
end

local function classifyProgressUnit(path)
    local low = string.lower(path or "")
    if string.find(low, "strength", 1, true) then return "strength" end
    if string.find(low, ".reps.progress", 1, true) then return "reps" end
    if string.find(low, ".minutes.progress", 1, true) then return "minutes" end
    if string.find(low, "agility", 1, true) then return "agility" end
    if string.find(low, ".claimed", 1, true) then return "claimed" end
    return "other"
end

local function refreshFeatureProgress(feature)
    local deltaEvents = 0
    local deltaByUnit = {}
    for _, path in ipairs(feature.monitorPaths) do
        local value = readNumber(path)
        if value ~= nil then
            local previous = feature.monitorValues[path]
            if previous ~= nil and value > previous then
                local delta = value - previous
                local unit = classifyProgressUnit(path)
                feature.progressEvents += 1
                feature.progressTotal += delta
                feature.progressionByUnit[unit] = (feature.progressionByUnit[unit] or 0) + delta
                feature.lastProgress = string.format("%s (+%s %s)", path, tostring(round(delta, 3)), unit)
                deltaEvents += 1
                deltaByUnit[unit] = (deltaByUnit[unit] or 0) + delta
            end
            feature.monitorValues[path] = value
            feature.unresolvedPaths[path] = nil

            for _, targetId in ipairs(feature.statTargetOrder or {}) do
                local target = feature.statTargets[targetId]
                local runtimeTarget = feature.statRuntime[targetId]
                if target and runtimeTarget and target.path == path then
                    if runtimeTarget.currentValue ~= nil and value > runtimeTarget.currentValue then
                        local statDelta = value - runtimeTarget.currentValue
                        runtimeTarget.totalGain = (runtimeTarget.totalGain or 0) + statDelta
                        runtimeTarget.progressEvents = (runtimeTarget.progressEvents or 0) + 1
                        runtimeTarget.lastStatus = string.format("+%s", tostring(round(statDelta, 3)))
                    end
                    runtimeTarget.currentValue = value
                    if runtimeTarget.initialValue == nil then
                        runtimeTarget.initialValue = value
                    end
                    local elapsed = math.max(0.01, os.clock() - state.startClock)
                    runtimeTarget.gainPerMinute = ((runtimeTarget.totalGain or 0) / elapsed) * 60
                end
            end
        else
            feature.unresolvedPaths[path] = true
        end
    end

    if feature.pendingTrainingMethodId and deltaEvents > 0 then
        local stats = feature.trainingMethodStats[feature.pendingTrainingMethodId]
        if stats then
            stats.progressEvents += deltaEvents
            for unit, delta in pairs(deltaByUnit) do
                stats.progressionByUnit[unit] = (stats.progressionByUnit[unit] or 0) + delta
            end
            stats.lastStatus = "progress observed"
        end
        feature.pendingTrainingMethodId = nil
        feature.pendingTrainingMethodProgressSnapshot = feature.progressEvents
    end
end

local function markOutcome(feature, stateName, statusText)
    feature.outcomeState = stateName
    if statusText then
        feature.lastStatus = statusText
    end
    if stateName == "action-verified-in-gameplay" then
        feature.verifiedOutcomes += 1
    elseif stateName == "action-invoked-outcome-unverified" then
        feature.unverifiedOutcomes += 1
    elseif stateName == "blocked-by-eligibility" then
        feature.blockedOutcomes += 1
    elseif stateName == "unsupported-interaction" then
        feature.unsupportedOutcomes += 1
    elseif stateName == "runtime-failure" then
        feature.runtimeFailureOutcomes += 1
    end
end

local function selectedTrainingMethodIds(feature)
    local selected = {}
    local seen = {}

    local hasStatTargets = #(feature.statTargetOrder or {}) > 0
    if hasStatTargets then
        for _, targetId in ipairs(feature.statTargetOrder or {}) do
            if feature.activeStatTargets[targetId] ~= false then
                local runtimeTarget = feature.statRuntime[targetId] or {}
                local localSelections = runtimeTarget.selectedMethodIds or {}
                for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
                    if localSelections[methodId] and feature.selectedTrainingMethodIds[methodId] and not seen[methodId] then
                        seen[methodId] = true
                        selected[#selected + 1] = methodId
                    end
                end
            end
        end
    end

    if #selected == 0 and not hasStatTargets then
        for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
            if feature.selectedTrainingMethodIds[methodId] and not seen[methodId] then
                seen[methodId] = true
                selected[#selected + 1] = methodId
            end
        end
    end

    return selected
end

local function chooseTrainingMethod(feature)
    local selected = selectedTrainingMethodIds(feature)
    if #selected == 0 then
        if #(feature.statTargetOrder or {}) > 0 then
            return nil, "no active stat targets with selected methods"
        end
        return nil, "no training methods selected"
    end

    local now = os.clock()
    for _ = 1, #selected do
        feature.trainingMethodCursor = (feature.trainingMethodCursor % #selected) + 1
        local methodId = selected[feature.trainingMethodCursor]
        local stats = feature.trainingMethodStats[methodId]
        if not stats or (stats.unavailableUntil or 0) <= now then
            return methodId, nil
        end
    end

    return nil, "selected training methods temporarily unavailable"
end

local function markMethodBlocked(feature, methodId, reason, backoffSeconds)
    local stats = feature.trainingMethodStats[methodId]
    if not stats then return end
    stats.errors += 1
    stats.lastError = reason
    stats.lastStatus = "blocked: " .. tostring(reason)
    stats.unavailableUntil = os.clock() + (backoffSeconds or 8.0)
end

local function armVerification(feature)
    feature.pendingVerification = true
    feature.lastInvokeAt = os.clock()
    feature.verifyEventSnapshot = feature.progressEvents
end

local function reconcileVerification(feature)
    if feature.pendingTrainingMethodId and feature.lastInvokeAt then
        local methodWindow = math.max(1.5, SETTINGS.delayedOutcomeWindowSeconds * 1.5)
        if (os.clock() - feature.lastInvokeAt) >= methodWindow then
            local stats = feature.trainingMethodStats[feature.pendingTrainingMethodId]
            if stats and stats.lastStatus == "activation sent" then
                stats.lastStatus = "no progress verified yet"
            end
            feature.pendingTrainingMethodId = nil
        end
    end

    if not feature.pendingVerification then return end
    local outcomeContract = feature.definition.outcomeContract or {}
    local window = tonumber(outcomeContract.verificationWindowSeconds) or math.max(2.0, SETTINGS.delayedOutcomeWindowSeconds * 2.0)

    if feature.progressEvents > (feature.verifyEventSnapshot or 0) then
        feature.pendingVerification = false
        markOutcome(feature, "action-verified-in-gameplay", "outcome verified by state delta")
        return
    end

    if feature.lastInvokeAt and (os.clock() - feature.lastInvokeAt) >= window then
        feature.pendingVerification = false
        markOutcome(feature, "action-invoked-outcome-unverified", "action sent; no verified reward-state change")
    end
end


local function disconnectCharacterConnections()
    for _, connection in ipairs(characterConnections) do
        pcall(function() connection:Disconnect() end)
    end
    characterConnections = {}
end

local function clearTrainingMethodBackoffWindows()
    for _, feature in ipairs(featureOrder) do
        if feature.action.kind == "tool_activate_selectable" then
            for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
                local stats = feature.trainingMethodStats[methodId]
                if stats then
                    stats.unavailableUntil = 0
                end
            end
        end
    end
end

local function selectRecoveryMethodId(feature)
    if not feature then return nil end
    if type(feature.lastTrainingMethodId) == "string" and feature.selectedTrainingMethodIds[feature.lastTrainingMethodId] then
        return feature.lastTrainingMethodId
    end
    for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
        if feature.selectedTrainingMethodIds[methodId] then
            return methodId
        end
    end
    return nil
end

local function setRespawnSuspended(reason)
    local lifecycle = state.characterLifecycle
    lifecycle.respawnSuspended = true
    lifecycle.suspensionReason = tostring(reason or "respawn recovery pending")
end

local function beginLifecycleRecovery(triggerReason)
    local lifecycle = state.characterLifecycle
    if not state.alive then return end
    local now = os.clock()
    if lifecycle.recoveryInProgress then return end
    if now < (lifecycle.nextRecoveryAttemptAt or 0) then return end

    lifecycle.recoveryInProgress = true
    lifecycle.recoveryAttempts += 1
    lifecycle.recoveryToken += 1
    local token = lifecycle.recoveryToken
    local startClock = os.clock()
    lifecycle.lastRecoveryStartClock = startClock
    lifecycle.lastFailureReason = nil
    setRespawnSuspended(triggerReason or "respawn recovery pending")

    task.spawn(function()
        local timeoutAt = startClock + 18.0
        while state.alive and token == lifecycle.recoveryToken do
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local backpack = player:FindFirstChild("Backpack")
            local humanoidReady = humanoid and humanoid.Health > 0

            if character and humanoidReady and backpack then
                disconnectCharacterConnections()
                characterConnections[#characterConnections + 1] = humanoid.Died:Connect(function()
                    lifecycle.deathCount += 1
                    setRespawnSuspended("humanoid died")
                    lifecycle.nextRecoveryAttemptAt = math.max(lifecycle.nextRecoveryAttemptAt or 0, os.clock() + 0.1)
                    beginLifecycleRecovery("humanoid died")
                end)

                lifecycle.characterGeneration += 1
                lifecycle.lastCharacterId = tostring(character)
                clearTrainingMethodBackoffWindows()

                local autoTrainFeature = features["auto_train"]
                local equipBlocked = false
                if autoTrainFeature and autoTrainFeature.running and autoTrainFeature.action.kind == "tool_activate_selectable" then
                    local methodId = selectRecoveryMethodId(autoTrainFeature)
                    if methodId then
                        local method = autoTrainFeature.trainingMethods[methodId] or {}
                        local tool = resolveTool(method.path, method.name)
                        if tool and tool:IsA("Tool") then
                            if tool.Parent ~= character then
                                pcall(function() humanoid:EquipTool(tool) end)
                            end
                            lifecycle.missingToolRetryCount = 0
                            autoTrainFeature.lastStatus = "respawn recovered; tool re-equipped"
                        else
                            lifecycle.missingToolRetryCount += 1
                            equipBlocked = true
                            local waitBackoff = clamp(0.4 * (2 ^ math.min(lifecycle.missingToolRetryCount, 4)), 0.5, 6.0)
                            lifecycle.nextRecoveryAttemptAt = os.clock() + waitBackoff
                            autoTrainFeature.lastStatus = "respawn recovered; waiting for selected tool"
                        end
                    end
                end

                if not equipBlocked then
                    local duration = os.clock() - startClock
                    lifecycle.lastRecoveryDurationSeconds = duration
                    lifecycle.recoveryTotalDurationSeconds += duration
                    lifecycle.recoverySuccesses += 1
                    lifecycle.recoveryInProgress = false
                    lifecycle.respawnSuspended = false
                    lifecycle.suspensionReason = "ready"
                    lifecycle.nextRecoveryAttemptAt = os.clock() + 0.2
                    return
                end
            end

            if os.clock() >= timeoutAt then
                local duration = os.clock() - startClock
                lifecycle.lastRecoveryDurationSeconds = duration
                lifecycle.recoveryTotalDurationSeconds += duration
                lifecycle.recoveryFailures += 1
                lifecycle.recoveryInProgress = false
                lifecycle.lastFailureReason = "replacement character/tool unavailable within timeout"
                lifecycle.suspensionReason = "temporary recovery failure"
                local retryBackoff = clamp(1.0 * (2 ^ math.min(lifecycle.recoveryFailures, 4)), 1.0, 12.0)
                lifecycle.nextRecoveryAttemptAt = os.clock() + retryBackoff
                return
            end

            task.wait(0.2)
        end
        lifecycle.recoveryInProgress = false
    end)
end

local function ensureTrainingCharacterReady(feature)
    local lifecycle = state.characterLifecycle
    local now = os.clock()
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not humanoid or humanoid.Health <= 0 then
        setRespawnSuspended("character unavailable")
        if now >= (lifecycle.nextRecoveryAttemptAt or 0) then
            beginLifecycleRecovery("character unavailable")
        end
        if feature then
            feature.lastStatus = "temporarily suspended: respawn recovery"
        end
        return nil, nil, "respawn recovery pending"
    end

    if lifecycle.respawnSuspended then
        if not lifecycle.recoveryInProgress and now >= (lifecycle.nextRecoveryAttemptAt or 0) then
            beginLifecycleRecovery("resume after respawn")
        end
        if feature then
            feature.lastStatus = "temporarily suspended: " .. tostring(lifecycle.suspensionReason)
        end
        return nil, nil, "respawn recovery pending"
    end

    return character, humanoid, nil
end

local function executeFeature(feature)
    local action = feature.action or {}
    local kind = action.kind
    feature.attempts += 1

    if kind == "tool_activate_selectable" then
        local methodId, pickError = chooseTrainingMethod(feature)
        if not methodId then
            markOutcome(feature, "blocked-by-eligibility", tostring(pickError))
            return
        end

        local method = feature.trainingMethods[methodId] or {}
        local stats = feature.trainingMethodStats[methodId]
        if stats then
            stats.attempts += 1
            stats.lastStatus = "attempting"
        end

        local character, humanoid, suspendReason = ensureTrainingCharacterReady(feature)
        if not character or not humanoid then
            markOutcome(feature, "blocked-by-eligibility", tostring(suspendReason or "respawn recovery pending"))
            return
        end

        local tool = resolveTool(method.path, method.name)
        if not tool or not tool:IsA("Tool") then
            feature.errors += 1
            feature.lastError = "training method unavailable: " .. tostring(method.name or methodId)
            local unavailableCount = (stats and (stats.errors or 0) or 0) + 1
            local backoff = clamp(0.8 * (2 ^ math.min(unavailableCount, 4)), 1.0, 12.0)
            markMethodBlocked(feature, methodId, "tool unavailable", backoff)
            markOutcome(feature, "blocked-by-eligibility", "training method unavailable: " .. tostring(method.name or methodId))
            return
        end

        if tool.Parent ~= character then
            pcall(function() humanoid:EquipTool(tool) end)
            task.wait(0.05)
        end

        local ok, err = pcall(function() tool:Activate() end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            if stats then
                stats.errors += 1
                stats.lastError = tostring(err)
                stats.lastStatus = "activation failed"
            end
            markOutcome(feature, "runtime-failure", "training method activation failed")
            return
        end

        feature.successes += 1
        feature.successfulCalls += 1
        feature.lastTrainingMethodId = methodId
        feature.lastInvokeAt = os.clock()
        feature.pendingTrainingMethodId = methodId
        feature.pendingTrainingMethodProgressSnapshot = feature.progressEvents
        if stats then
            stats.successes += 1
            stats.lastStatus = "activation sent"
        end
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "activation sent: " .. tostring(method.name or methodId)
        return
    end

    if kind == "tool_activate" then
        local character, humanoid, suspendReason = ensureTrainingCharacterReady(feature)
        if not character or not humanoid then
            markOutcome(feature, "blocked-by-eligibility", tostring(suspendReason or "respawn recovery pending"))
            return
        end
        local tool = resolveTool(action.toolPath, action.toolName)
        if not tool then
            feature.errors += 1
            feature.lastError = "tool unavailable"
            markOutcome(feature, "blocked-by-eligibility", "tool unavailable")
            return
        end
        if tool.Parent ~= character then
            pcall(function() humanoid:EquipTool(tool) end)
            task.wait(0.05)
        end
        local ok, err = pcall(function() tool:Activate() end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            markOutcome(feature, "runtime-failure", "activation failed")
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "activation sent"
        return
    end

    if kind == "ensure_tool_equipped" then
        local character, humanoid, suspendReason = ensureTrainingCharacterReady(feature)
        if not character or not humanoid then
            markOutcome(feature, "blocked-by-eligibility", tostring(suspendReason or "respawn recovery pending"))
            return
        end
        local tool = resolveTool(action.toolPath, action.toolName)
        if not tool then
            feature.errors += 1
            feature.lastError = "tool unavailable"
            markOutcome(feature, "blocked-by-eligibility", "equip unavailable")
            return
        end
        local ok, err = pcall(function() humanoid:EquipTool(tool) end)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            markOutcome(feature, "runtime-failure", "equip failed")
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "equip requested"
        return
    end

    if kind == "auto_rewards_discovery" then
        if feature.monitorOnlyFallback then
            feature.lastStatus = "reward monitoring fallback active"
            feature.outcomeState = "action-invoked-outcome-unverified"
            return
        end

        local candidates = {}
        local seen = {}

        local function candidateKey(button, pathHint, role)
            local key = tostring(pathHint or "")
            if key == "" then
                local ok, fullName = pcall(function() return button:GetFullName() end)
                if ok and type(fullName) == "string" and fullName ~= "" then
                    key = fullName
                else
                    key = tostring(button)
                end
            end
            return tostring(role or "candidate") .. "::" .. key
        end

        local function pushCandidateObject(button, role, pathHint)
            if not button or not button:IsA("GuiButton") then return end
            local lowName = string.lower(button.Name or "")
            if string.find(lowName, "buy", 1, true) or string.find(lowName, "robux", 1, true) or string.find(lowName, "vip", 1, true) then
                return
            end

            local normalizedRole = role or "claim"
            if string.find(lowName, "spin", 1, true) or string.find(lowName, "wheel", 1, true) then
                normalizedRole = "open"
            end

            local key = candidateKey(button, pathHint, normalizedRole)
            if seen[key] then return end
            seen[key] = true
            candidates[#candidates + 1] = {
                button = button,
                role = normalizedRole,
                key = key,
                pathHint = pathHint,
            }
        end

        local function pushCandidateFromPath(path, role)
            if type(path) ~= "string" then return end
            local lowPath = string.lower(path)
            if string.find(lowPath, ".claimed", 1, true) or string.find(lowPath, ".timer", 1, true) or string.find(lowPath, ".readytext", 1, true) then
                return
            end
            local button = resolveActionableGuiButton(path, role == "claim" and "claim" or "open")
            if not button then return end
            pushCandidateObject(button, role, path)
        end

        local explicitClaimPaths = {}
        for _, claimPath in ipairs(action.claimPaths or {}) do
            explicitClaimPaths[tostring(claimPath)] = true
        end

        for _, path in ipairs(action.paths or {}) do
            local pathText = tostring(path)
            local lowPath = string.lower(pathText)
            local role = explicitClaimPaths[pathText] and "claim" or ((string.find(lowPath, "claim", 1, true) or string.find(lowPath, "collect", 1, true) or string.find(lowPath, "hitbox", 1, true)) and "claim" or "open")
            pushCandidateFromPath(path, role)
        end

        for _, containerPath in ipairs(action.rewardContainerPaths or {}) do
            local container = resolvePath(containerPath)
            if container then
                for _, descendant in ipairs(container:GetDescendants()) do
                    local lowName = string.lower(descendant.Name or "")
                    if descendant:IsA("GuiButton") and (
                        string.find(lowName, "hitbox", 1, true)
                        or string.find(lowName, "claim", 1, true)
                        or string.find(lowName, "collect", 1, true)
                    ) then
                        pushCandidateObject(descendant, "claim", containerPath .. "." .. tostring(descendant.Name or "button"))
                    end
                end
            end
        end

        local function isEligible(entry)
            local obj = entry.button
            if not obj.Visible then return false, "hidden" end
            local parent = obj.Parent
            if not parent then return true, "no-parent" end

            local claimed = parent:FindFirstChild("Claimed", true)
            if claimed and claimed:IsA("GuiObject") and claimed.Visible then
                return false, "already-claimed"
            end

            local timer = parent:FindFirstChild("Timer", true)
            if timer and timer:IsA("TextLabel") then
                local text = string.lower(timer.Text or "")
                if text ~= "" and text ~= "0" and text ~= "00:00" and text ~= "00:00:00" then
                    return false, "cooldown"
                end
            end

            local readyText = parent:FindFirstChild("ReadyText", true)
            if readyText and readyText:IsA("GuiObject") then
                if readyText.Visible then return true, "ready-text-visible" end
                if readyText:IsA("TextLabel") and string.find(string.lower(readyText.Text or ""), "ready", 1, true) then
                    return true, "ready-text-content"
                end
            end

            if entry.role == "open" then
                return true, "open-navigation"
            end
            return true, "no-indicator"
        end

        local function listenerCount(obj)
            if type(getconnections) ~= "function" then return nil end
            local total = 0
            local okClick, clickConnections = pcall(function() return getconnections(obj.MouseButton1Click) end)
            if okClick and type(clickConnections) == "table" then total += #clickConnections end
            local okActivated, activatedConnections = pcall(function() return getconnections(obj.Activated) end)
            if okActivated and type(activatedConnections) == "table" then total += #activatedConnections end
            return total
        end

        if #candidates == 0 then
            feature.unresolvedActionableAttempts += 1
            if feature.unresolvedActionableAttempts >= 3 then
                feature.monitorOnlyFallback = true
                markOutcome(feature, "unsupported-interaction", "no executable reward claim control; monitor-only fallback")
            else
                markOutcome(feature, "blocked-by-eligibility", "no reward claim controls resolved")
            end
            return
        end

        local now = os.clock()
        local availableCandidates = {}
        for _, candidate in ipairs(candidates) do
            local blockedUntil = feature.candidateCooldowns[candidate.key] or 0
            if blockedUntil <= now then
                availableCandidates[#availableCandidates + 1] = candidate
            end
        end

        if #availableCandidates == 0 then
            markOutcome(feature, "blocked-by-eligibility", "reward candidates cooling down")
            return
        end

        local claimCandidates = {}
        local openCandidates = {}
        for _, candidate in ipairs(availableCandidates) do
            if candidate.role == "claim" then
                claimCandidates[#claimCandidates + 1] = candidate
            else
                openCandidates[#openCandidates + 1] = candidate
            end
        end

        local candidatePool = (#claimCandidates > 0) and claimCandidates or openCandidates
        feature.cursor = (feature.cursor % #candidatePool) + 1
        local target = candidatePool[feature.cursor]
        local targetKey = target.key

        local eligible, reason = isEligible(target)
        if not eligible then
            local backoff = 4.0
            if reason == "cooldown" then backoff = 12.0 end
            if reason == "already-claimed" then backoff = 30.0 end
            feature.candidateCooldowns[targetKey] = now + backoff
            markOutcome(feature, "blocked-by-eligibility", "reward not eligible: " .. tostring(reason))
            return
        end

        local listeners = listenerCount(target.button)
        if listeners ~= nil and listeners <= 0 and not runtimeCapabilities.firesignal then
            feature.candidateCooldowns[targetKey] = now + 15.0
            markOutcome(feature, "unsupported-interaction", "no reward listeners and no firesignal")
            return
        end

        local ok, methodOrErr = activateGuiObject(target.button)
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(methodOrErr)
            feature.candidateCooldowns[targetKey] = now + 8.0
            if string.find(tostring(methodOrErr), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "reward trigger unsupported")
            else
                markOutcome(feature, "runtime-failure", "reward trigger runtime failure")
            end
            return
        end

        feature.successes += 1
        feature.successfulCalls += 1
        if target.role == "claim" then
            feature.candidateCooldowns[targetKey] = now + 2.0
            feature.lastStatus = "reward claim trigger sent via " .. tostring(methodOrErr)
            feature.outcomeState = "action-invoked-outcome-unverified"
            feature.unresolvedActionableAttempts = 0
            armVerification(feature)
        else
            feature.candidateCooldowns[targetKey] = now + 8.0
            markOutcome(feature, "blocked-by-eligibility", "reward navigation sent; waiting for claim-eligible control")
        end
        return
    end

    if kind == "quest_train_workflow" then
        local autoTrainFeature = features["auto_train"]
        if not autoTrainFeature or not autoTrainFeature.running then
            markOutcome(feature, "blocked-by-eligibility", "auto_train dependency not running")
            return
        end

        if feature.monitorOnlyFallback then
            feature.lastStatus = "quest monitor-only fallback active"
            feature.outcomeState = "action-invoked-outcome-unverified"
            return
        end

        local questPaths = {}
        for _, path in ipairs(action.questOpenPaths or {}) do
            questPaths[#questPaths + 1] = {path = path, kind = "open"}
        end
        for _, path in ipairs(action.questClaimPaths or {}) do
            questPaths[#questPaths + 1] = {path = path, kind = "claim"}
        end

        if #questPaths > 0 then
            local now = os.clock()
            local available = {}
            for _, item in ipairs(questPaths) do
                local key = tostring(item.kind) .. "::" .. tostring(item.path)
                local blockedUntil = feature.candidateCooldowns[key] or 0
                if blockedUntil <= now then
                    item.key = key
                    available[#available + 1] = item
                end
            end

            if #available == 0 then
                markOutcome(feature, "blocked-by-eligibility", "quest controls cooling down")
                return
            end

            feature.cursor = (feature.cursor % #available) + 1
            local item = available[feature.cursor]
            local qOk, qErr = activateGuiPath(item.path, item.kind == "claim" and "claim" or "open")
            if qOk then
                feature.successfulCalls += 1
                feature.successes += 1
                feature.unresolvedActionableAttempts = 0
                feature.candidateCooldowns[item.key] = now + (item.kind == "claim" and 2.0 or 6.0)
                feature.outcomeState = "action-invoked-outcome-unverified"
                feature.lastStatus = "quest " .. tostring(item.kind) .. " action sent"
                if item.kind == "claim" then
                    armVerification(feature)
                end
                return
            end

            feature.lastError = tostring(qErr)
            feature.errors += 1
            feature.candidateCooldowns[item.key] = now + 8.0
            if string.find(tostring(qErr), "no actionable GuiButton resolved", 1, true) or string.find(tostring(qErr), "object is not GuiButton", 1, true) then
                feature.unresolvedActionableAttempts += 1
                if feature.unresolvedActionableAttempts >= 3 then
                    feature.monitorOnlyFallback = true
                    markOutcome(feature, "unsupported-interaction", "quest actionable controls unresolved; monitor-only fallback")
                else
                    markOutcome(feature, "blocked-by-eligibility", "quest actionable button unresolved")
                end
            elseif string.find(tostring(qErr), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "quest interface trigger unsupported")
            else
                markOutcome(feature, "runtime-failure", "quest interface action failed")
            end
            return
        end

        feature.successes += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "quest monitoring via auto_train dependency"
        return
    end


    if kind == "gui_activate_many" then
        local paths = action.paths or {}
        if #paths == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no actionable GUI paths")
            return
        end
        feature.cursor = (feature.cursor % #paths) + 1
        local ok, err = activateGuiPath(paths[feature.cursor])
        if not ok then
            feature.errors += 1
            feature.lastError = tostring(err)
            if string.find(tostring(err), "no-supported-gui-trigger", 1, true) then
                markOutcome(feature, "unsupported-interaction", "gui activation unsupported")
            else
                markOutcome(feature, "runtime-failure", "gui activation failed")
            end
            return
        end
        feature.successes += 1
        feature.successfulCalls += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "gui activation sent"
        return
    end

    if kind == "gui_sequence" then
        local steps = action.steps or {}
        if #steps == 0 then
            markOutcome(feature, "blocked-by-eligibility", "no sequence steps")
            return
        end
        for _, step in ipairs(steps) do
            if step.kind == "gui_activate" then
                local ok, err = activateGuiPath(step.path)
                if not ok then
                    feature.errors += 1
                    feature.lastError = tostring(err)
                    if string.find(tostring(err), "no-supported-gui-trigger", 1, true) then
                        markOutcome(feature, "unsupported-interaction", "sequence trigger unsupported")
                    else
                        markOutcome(feature, "runtime-failure", "sequence failed")
                    end
                    return
                end
                feature.successfulCalls += 1
                task.wait(0.05)
            end
        end
        feature.successes += 1
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "sequence sent"
        return
    end

    if kind == "observe_only" then
        feature.outcomeState = "action-invoked-outcome-unverified"
        feature.lastStatus = "monitor only"
        return
    end

    feature.outcomeState = "action-invoked-outcome-unverified"
    feature.lastStatus = "monitor only"
end

local function stopFeature(feature, reason)
    feature.running = false
    feature.pendingVerification = false
    feature.token += 1
    feature.lastStatus = reason or feature.lastStatus
end

local function startFeature(feature, visited)
    if not feature.supported then
        feature.lastStatus = "unavailable"
        return
    end
    if feature.running then
        feature.lastStatus = "already running"
        return
    end

    visited = visited or {}
    if visited[feature.id] then return end
    visited[feature.id] = true

    local dependencies = featureDependencies[feature.id] or {}
    for _, dependencyId in ipairs(dependencies) do
        local dependencyFeature = features[dependencyId]
        if dependencyFeature and not dependencyFeature.running then
            startFeature(dependencyFeature, visited)
        end
    end

    if feature.destructive then
        local now = os.clock()
        feature.confirmUntil = feature.confirmUntil or 0
        if now > feature.confirmUntil then
            feature.confirmUntil = now + 5.0
            markOutcome(feature, "blocked-by-eligibility", "confirmation required: press START again within 5s")
            return
        end
        feature.confirmUntil = 0
    end

    feature.running = true
    feature.token += 1
    local token = feature.token
    feature.lastStatus = "running"
    task.spawn(function()
        while state.alive and feature.running and token == feature.token do
            executeFeature(feature)
            local waitTime = clamp(feature.intervalSeconds * state.intervalScale, SETTINGS.minActivationIntervalSeconds, SETTINGS.maxActivationIntervalSeconds)
            task.wait(waitTime)
        end
    end)
end

local function startAll()
    for _, feature in ipairs(featureOrder) do
        if feature.supported and feature.includeInStartAll and not feature.destructive then
            startFeature(feature)
        end
    end
    state.lastStatus = "start-all issued"
end

local function stopAll(reason)
    for _, feature in ipairs(featureOrder) do
        if feature.running then
            stopFeature(feature, reason or "stopped")
        end
    end
end

local function buildDiagnosticReport()
    local featureReports = {}
    local successfulApiCalls = 0
    local runtimeErrors = {}
    local observedStateChanges = {}

    for _, feature in ipairs(featureOrder) do
        successfulApiCalls += feature.successfulCalls
        if feature.lastError then
            runtimeErrors[#runtimeErrors + 1] = {featureId = feature.id, message = feature.lastError}
        end
        local unresolved = {}
        for path, unresolvedFlag in pairs(feature.unresolvedPaths or {}) do
            if unresolvedFlag then unresolved[#unresolved + 1] = path end
        end

        observedStateChanges[#observedStateChanges + 1] = {
            featureId = feature.id,
            progressionEvents = feature.progressEvents,
            progressionTotal = round(feature.progressTotal, 6),
            progressionByUnit = feature.progressionByUnit,
            unresolvedPaths = unresolved,
            lastProgression = feature.lastProgress,
        }
        featureReports[#featureReports + 1] = {
            id = feature.id,
            title = feature.title,
            supported = feature.supported,
            includeInStartAll = feature.includeInStartAll,
            destructive = feature.destructive,
            attempts = feature.attempts,
            successes = feature.successes,
            successfulApiCalls = feature.successfulCalls,
            errors = feature.errors,
            progressionEvents = feature.progressEvents,
            progressionTotal = round(feature.progressTotal, 6),
            progressionByUnit = feature.progressionByUnit,
            unresolvedPaths = unresolved,
            status = feature.lastStatus,
            outcomeState = feature.outcomeState,
            outcomeCounters = {
                verified = feature.verifiedOutcomes,
                unverified = feature.unverifiedOutcomes,
                blocked = feature.blockedOutcomes,
                unsupported = feature.unsupportedOutcomes,
                runtimeFailure = feature.runtimeFailureOutcomes,
            },
            trainingMethods = (function()
                if feature.action.kind ~= "tool_activate_selectable" then return nil end
                local rowsLocal = {}
                for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
                    local method = feature.trainingMethods[methodId] or {}
                    local stats = feature.trainingMethodStats[methodId] or {}
                    rowsLocal[#rowsLocal + 1] = {
                        id = methodId,
                        name = method.name,
                        path = method.path,
                        source = method.source,
                        selected = feature.selectedTrainingMethodIds[methodId] == true,
                        statTargetIds = feature.methodStatMap[methodId] or {},
                        candidateStats = method.candidateStats or {},
                        attempts = stats.attempts or 0,
                        successes = stats.successes or 0,
                        errors = stats.errors or 0,
                        progressEvents = stats.progressEvents or 0,
                        progressionByUnit = stats.progressionByUnit or {},
                        lastStatus = stats.lastStatus,
                    }
                end
                return rowsLocal
            end)(),
            statTargets = (function()
                if feature.action.kind ~= "tool_activate_selectable" then return nil end
                local rowsLocal = {}
                for _, targetId in ipairs(feature.statTargetOrder or {}) do
                    local target = feature.statTargets[targetId] or {}
                    local runtimeTarget = feature.statRuntime[targetId] or {}
                    rowsLocal[#rowsLocal + 1] = {
                        id = targetId,
                        name = target.name,
                        path = target.path,
                        confidenceScore = target.confidenceScore,
                        confidenceLevel = target.confidenceLevel,
                        active = feature.activeStatTargets[targetId] ~= false,
                        selectedMethodIds = (function()
                            local ids = {}
                            for methodId, enabled in pairs(runtimeTarget.selectedMethodIds or {}) do
                                if enabled then ids[#ids + 1] = methodId end
                            end
                            table.sort(ids)
                            return ids
                        end)(),
                        currentValue = runtimeTarget.currentValue,
                        initialValue = runtimeTarget.initialValue,
                        totalGain = runtimeTarget.totalGain,
                        gainPerMinute = runtimeTarget.gainPerMinute,
                        progressEvents = runtimeTarget.progressEvents,
                        status = runtimeTarget.lastStatus,
                        unsupportedReason = target.unsupportedReason,
                    }
                end
                return rowsLocal
            end)(),
            monitorOnlyFallback = feature.monitorOnlyFallback == true,
            unresolvedActionableAttempts = feature.unresolvedActionableAttempts or 0,
            actionable = feature.definition.actionable,
            evidence = feature.definition.evidence,
        }
    end

    local sessionStrengthNetChange = nil
    if state.currentStrength ~= nil and state.initialStrength ~= nil then
        sessionStrengthNetChange = round(state.currentStrength - state.initialStrength, 6)
    end

    local attributedStrengthTotal = 0
    for _, feature in ipairs(featureOrder) do
        attributedStrengthTotal += tonumber(feature.progressionByUnit.strength or 0) or 0
    end

    return {
        schemaVersion = "lycoles.batch-diagnostic.1",
        game = {
            gameName = CONTRACT.gameName,
            placeId = CONTRACT.placeId,
            gameId = game.GameId,
        },
        versions = {
            inspectorSchemaVersion = ((CONTRACT.generatorMetadata or {}).inspectorSchemaVersion),
            projectVersion = ((CONTRACT.generatorMetadata or {}).projectVersion),
            generatorVersion = ((CONTRACT.generatorMetadata or {}).generatorVersion),
        },
        generatedFeatureList = CONTRACT.generatedFeatureIds or {},
        featureDependencies = CONTRACT.featureDependencies or {},
        deduplicatedFeatures = CONTRACT.deduplicatedFeatures or {},
        trainingDiscovery = CONTRACT.trainingDiscovery or {},
        runtimeCapabilities = runtimeCapabilities,
        featureReports = featureReports,
        successfulApiCalls = successfulApiCalls,
        runtimeErrors = runtimeErrors,
        observedStateChanges = observedStateChanges,
        delayedProgressionOutcomes = {
            strengthPath = globalStrengthPath,
            strengthPathResolved = (state.currentStrength ~= nil),
            currentStrength = state.currentStrength,
            initialStrength = state.initialStrength,
            totalStrengthGain = round(state.totalStrengthGain, 6),
            sessionStrengthNetChange = sessionStrengthNetChange,
            strengthGainPerMinute = round(state.strengthGainPerMinute, 6),
            stalled = state.stalled,
        },
        progressionAccounting = {
            positiveStrengthDeltaObserved = round(state.totalStrengthGain, 6),
            sessionStrengthNetChange = sessionStrengthNetChange,
            featureAttributedStrengthDeltaSum = round(attributedStrengthTotal, 6),
            attributionOvercountEstimate = round(attributedStrengthTotal - state.totalStrengthGain, 6),
        },
        characterLifecycle = {
            respawnSuspended = state.characterLifecycle.respawnSuspended,
            suspensionReason = state.characterLifecycle.suspensionReason,
            deathCount = state.characterLifecycle.deathCount,
            recoveryAttempts = state.characterLifecycle.recoveryAttempts,
            recoverySuccesses = state.characterLifecycle.recoverySuccesses,
            recoveryFailures = state.characterLifecycle.recoveryFailures,
            lastRecoveryDurationSeconds = round(state.characterLifecycle.lastRecoveryDurationSeconds or 0, 6),
            recoveryTotalDurationSeconds = round(state.characterLifecycle.recoveryTotalDurationSeconds or 0, 6),
            recoveryInProgress = state.characterLifecycle.recoveryInProgress,
            lastFailureReason = state.characterLifecycle.lastFailureReason,
            missingToolRetryCount = state.characterLifecycle.missingToolRetryCount,
            characterGeneration = state.characterLifecycle.characterGeneration,
        },
        unsupportedFeatures = CONTRACT.unsupportedFeatures or {},
        claims = CONTRACT.claims,
    }
end

local function exportDiagnosticReport()
    local encoded = HttpService:JSONEncode(buildDiagnosticReport())
    local copied = false
    if type(setclipboard) == "function" then
        pcall(function() setclipboard(encoded) end)
        copied = true
    elseif type(toclipboard) == "function" then
        pcall(function() toclipboard(encoded) end)
        copied = true
    elseif type(toClipboard) == "function" then
        pcall(function() toClipboard(encoded) end)
        copied = true
    end
    _G.LycolesLastDiagnosticReport = encoded
    if copied then
        state.lastStatus = "diagnostic report copied"
    else
        state.lastStatus = "clipboard unavailable; report printed and cached"
        print(encoded)
    end
end

