local function renderRows()
    local runningCount = 0
    for _, feature in ipairs(featureOrder) do
        local row = rows[feature.id]
        if feature.running then runningCount += 1 end
        if row then
            if not feature.supported then
                row.toggle.Text = "N/A"
                row.toggle.BackgroundColor3 = Color3.fromRGB(72, 74, 80)
                row.status.TextColor3 = Color3.fromRGB(220, 160, 160)
            elseif feature.running then
                row.toggle.Text = "STOP"
                row.toggle.BackgroundColor3 = Color3.fromRGB(140, 70, 70)
                row.status.TextColor3 = Color3.fromRGB(208, 216, 224)
            else
                if feature.destructive then
                    local confirmUntil = feature.confirmUntil or 0
                    if confirmUntil > os.clock() then
                        row.toggle.Text = "CONFIRM"
                    else
                        row.toggle.Text = "ARM"
                    end
                    row.toggle.BackgroundColor3 = Color3.fromRGB(150, 94, 58)
                else
                    row.toggle.Text = "START"
                    row.toggle.BackgroundColor3 = Color3.fromRGB(52, 118, 84)
                end
                row.status.TextColor3 = Color3.fromRGB(208, 216, 224)
            end

            if feature.outcomeState == "action-verified-in-gameplay" then
                row.status.TextColor3 = Color3.fromRGB(166, 222, 178)
            elseif feature.outcomeState == "blocked-by-eligibility" then
                row.status.TextColor3 = Color3.fromRGB(232, 207, 137)
            elseif feature.outcomeState == "unsupported-interaction" then
                row.status.TextColor3 = Color3.fromRGB(231, 156, 156)
            elseif feature.outcomeState == "runtime-failure" then
                row.status.TextColor3 = Color3.fromRGB(230, 122, 122)
            end

            local strengthDelta = round(feature.progressionByUnit.strength or 0, 3)
            local repsDelta = round(feature.progressionByUnit.reps or 0, 3)
            local statusText = string.format("status=%s | outcome=%s | lastProgress=%s", tostring(feature.lastStatus), tostring(feature.outcomeState), tostring(feature.lastProgress))
            if feature.id == "auto_train" then
                if feature.lastTrainingMethodId then
                    local method = feature.trainingMethods[feature.lastTrainingMethodId] or {}
                    statusText = statusText .. string.format(" | method=%s", tostring(method.name or feature.lastTrainingMethodId))
                end
                local lifecycle = state.characterLifecycle
                statusText = statusText .. string.format(" | recovery=%s/%s", tostring(lifecycle.respawnSuspended), tostring(lifecycle.suspensionReason))
            end
            row.status.Text = statusText

            if feature.id == "auto_train" and feature.action.kind == "tool_activate_selectable" then
                local selectedCount = 0
                local activeStatCount = 0
                for _, methodId in ipairs(feature.trainingMethodOrder or {}) do
                    if feature.selectedTrainingMethodIds[methodId] then selectedCount += 1 end
                end
                for _, targetId in ipairs(feature.statTargetOrder or {}) do
                    if feature.activeStatTargets[targetId] ~= false then activeStatCount += 1 end
                end
                row.metrics.Text = string.format("A:%d S:%d E:%d P:%d STR:+%s REP:+%s Sel:%d/%d Stats:%d/%d", feature.attempts, feature.successes, feature.errors, feature.progressEvents, tostring(strengthDelta), tostring(repsDelta), selectedCount, #feature.trainingMethodOrder, activeStatCount, #feature.statTargetOrder)
            else
                row.metrics.Text = string.format("A:%d S:%d E:%d P:%d STR:+%s REP:+%s V:%d U:%d B:%d F:%d", feature.attempts, feature.successes, feature.errors, feature.progressEvents, tostring(strengthDelta), tostring(repsDelta), feature.verifiedOutcomes, feature.unverifiedOutcomes, feature.blockedOutcomes, feature.runtimeFailureOutcomes)
            end
        end
    end

    local trainFeature = features["auto_train"]
    if trainFeature and trainFeature.action.kind == "tool_activate_selectable" then
        for targetId, ui in pairs(statTargetRows) do
            local target = trainFeature.statTargets[targetId] or {}
            local runtimeTarget = trainFeature.statRuntime[targetId] or {}
            local active = trainFeature.activeStatTargets[targetId] ~= false
            ui.toggle.Text = active and "ACTIVE" or "PAUSE"
            ui.toggle.BackgroundColor3 = active and Color3.fromRGB(52, 118, 84) or Color3.fromRGB(90, 88, 82)

            local confidenceText = tostring(target.confidenceLevel or "unknown")
            ui.label.Text = string.format("%s [%s]", tostring(target.name or targetId), confidenceText)
            local currentValue = runtimeTarget.currentValue ~= nil and tostring(round(runtimeTarget.currentValue, 3)) or "n/a"
            local gain = tostring(round(runtimeTarget.totalGain or 0, 3))
            local unsupportedReason = type(target.unsupportedReason) == "string" and target.unsupportedReason or nil
            if unsupportedReason then
                ui.status.Text = string.format("unsupported | %s", unsupportedReason)
            else
                ui.status.Text = string.format("%s | value=%s gain=%s/min=%s", tostring(runtimeTarget.lastStatus or ""), currentValue, gain, tostring(round(runtimeTarget.gainPerMinute or 0, 3)))
            end
        end

        for methodId, ui in pairs(trainingMethodRows) do
            local method = trainFeature.trainingMethods[methodId] or {}
            local stats = trainFeature.trainingMethodStats[methodId] or {}
            local selected = trainFeature.selectedTrainingMethodIds[methodId] == true
            ui.toggle.Text = selected and "ON" or "OFF"
            ui.toggle.BackgroundColor3 = selected and Color3.fromRGB(52, 118, 84) or Color3.fromRGB(82, 84, 90)

            local sourceTag = method.source == "world-station" and "[world]" or "[tool]"
            local safeTag = method.safeByDefault == false and " [manual]" or ""
            local mappedTargetNames = {}
            for _, targetId in ipairs(trainFeature.methodStatMap[methodId] or {}) do
                local target = trainFeature.statTargets[targetId]
                if target and target.name then
                    mappedTargetNames[#mappedTargetNames + 1] = tostring(target.name)
                end
            end
            local targetTag = #mappedTargetNames > 0 and (" -> " .. table.concat(mappedTargetNames, ",")) or ""
            ui.label.Text = string.format("%s %s%s%s", sourceTag, tostring(method.name or methodId), safeTag, targetTag)

            local strengthGain = round(((stats.progressionByUnit or {}).strength) or 0, 3)
            ui.status.Text = string.format("%s | A:%d S:%d E:%d P:%d STR:+%s", tostring(stats.lastStatus or ""), stats.attempts or 0, stats.successes or 0, stats.errors or 0, stats.progressEvents or 0, tostring(strengthGain))
        end
    end

    state.stalled = (runningCount > 0 and state.strengthGainPerMinute <= 0 and (os.clock() - state.startClock) > SETTINGS.stallWindowSeconds)
end

local function renderSummary()
    local elapsed = os.clock() - state.startClock
    local currentStrengthText = state.currentStrength and tostring(round(state.currentStrength, 3)) or "n/a"
    local initialStrengthText = state.initialStrength and tostring(round(state.initialStrength, 3)) or "n/a"
    local strengthResolved = state.currentStrength ~= nil
    local netChange = (state.currentStrength and state.initialStrength) and round(state.currentStrength - state.initialStrength, 3) or "n/a"

    local verified, unverified, blocked, unsupported, failures = 0, 0, 0, 0, 0
    for _, feature in ipairs(featureOrder) do
        if feature.outcomeState == "action-verified-in-gameplay" then
            verified += 1
        elseif feature.outcomeState == "action-invoked-outcome-unverified" then
            unverified += 1
        elseif feature.outcomeState == "blocked-by-eligibility" then
            blocked += 1
        elseif feature.outcomeState == "unsupported-interaction" then
            unsupported += 1
        elseif feature.outcomeState == "runtime-failure" then
            failures += 1
        end
    end

    speedLabel.Text = string.format("Global speed scale: %.2fx", state.intervalScale)
    local lifecycle = state.characterLifecycle
    local lines = {
        string.format("Strength current=%s initial=%s net=%s positiveDelta=%s gain/min=%s pathResolved=%s", currentStrengthText, initialStrengthText, tostring(netChange), tostring(round(state.totalStrengthGain, 3)), tostring(round(state.strengthGainPerMinute, 3)), tostring(strengthResolved)),
        string.format("Outcomes verified=%d unverified=%d blocked=%d unsupported=%d failures=%d", verified, unverified, blocked, unsupported, failures),
        string.format("Elapsed %.1fs | stalled=%s | status=%s", elapsed, tostring(state.stalled), tostring(state.lastStatus)),
        string.format("Recovery suspended=%s reason=%s deaths=%d attempts=%d ok=%d fail=%d last=%.2fs", tostring(lifecycle.respawnSuspended), tostring(lifecycle.suspensionReason), lifecycle.deathCount or 0, lifecycle.recoveryAttempts or 0, lifecycle.recoverySuccesses or 0, lifecycle.recoveryFailures or 0, tonumber(lifecycle.lastRecoveryDurationSeconds or 0)),
        string.format("Delayed window=%.2fs | unsupportedFeatures=%d", SETTINGS.delayedOutcomeWindowSeconds, #(CONTRACT.unsupportedFeatures or {})),
    }

    local trainFeature = features["auto_train"]
    if trainFeature and trainFeature.action.kind == "tool_activate_selectable" then
        local added = 0
        for _, targetId in ipairs(trainFeature.statTargetOrder or {}) do
            if added >= 3 then break end
            local target = trainFeature.statTargets[targetId] or {}
            local runtimeTarget = trainFeature.statRuntime[targetId] or {}
            local active = trainFeature.activeStatTargets[targetId] ~= false
            local valueText = runtimeTarget.currentValue ~= nil and tostring(round(runtimeTarget.currentValue, 3)) or "n/a"
            local gainText = tostring(round(runtimeTarget.totalGain or 0, 3))
            lines[#lines + 1] = string.format("Stat %s (%s) active=%s value=%s gain=%s/min=%s", tostring(target.name or targetId), tostring(target.confidenceLevel or "unknown"), tostring(active), valueText, gainText, tostring(round(runtimeTarget.gainPerMinute or 0, 3)))
            added += 1
        end
    end
    summary.Text = table.concat(lines, "\n")
end

local function closeAll()
    state.alive = false
    state.characterLifecycle.recoveryToken += 1
    stopAll("closed")
    disconnectCharacterConnections()
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    gui:Destroy()
    _G.LycolesMuscleAutoTrainStartAll = nil
    _G.LycolesMuscleAutoTrainStopAll = nil
    _G.LycolesMuscleAutoTrainExportReport = nil
    _G.LycolesMuscleAutoTrainClose = nil
end

local function setCollapsed(nextState)
    collapsed = nextState
    frame.Size = collapsed and collapsedSize or expandedSize
    summary.Visible = not collapsed
    controls.Visible = not collapsed
    list.Visible = not collapsed
    minimizeButton.Text = collapsed and "RESTORE" or "MIN"
end

setCollapsed(false)

startAllButton.MouseButton1Click:Connect(function() startAll() end)
stopAllButton.MouseButton1Click:Connect(function() stopAll("stop-all") state.lastStatus = "stop-all issued" end)
copyReportButton.MouseButton1Click:Connect(function() exportDiagnosticReport() end)
connections[#connections + 1] = minimizeButton.MouseButton1Click:Connect(function()
    setCollapsed(not collapsed)
end)
closeButton.MouseButton1Click:Connect(closeAll)

connections[#connections + 1] = speedMinus.MouseButton1Click:Connect(function()
    state.intervalScale = clamp(state.intervalScale - 0.05, 0.25, 3.0)
end)
connections[#connections + 1] = speedPlus.MouseButton1Click:Connect(function()
    state.intervalScale = clamp(state.intervalScale + 0.05, 0.25, 3.0)
end)

_G.LycolesMuscleAutoTrainStartAll = startAll
_G.LycolesMuscleAutoTrainStopAll = stopAll
_G.LycolesMuscleAutoTrainExportReport = exportDiagnosticReport
_G.LycolesMuscleAutoTrainClose = closeAll

task.spawn(function()
    while state.alive do
        local lifecycle = state.characterLifecycle
        if lifecycle.respawnSuspended and not lifecycle.recoveryInProgress and os.clock() >= (lifecycle.nextRecoveryAttemptAt or 0) then
            beginLifecycleRecovery("periodic recovery tick")
        end

        updateGlobalProgression()
        for _, feature in ipairs(featureOrder) do
            refreshFeatureProgress(feature)
            reconcileVerification(feature)
        end
        renderRows()
        renderSummary()
        task.wait(SETTINGS.pollIntervalSeconds)
    end
end)
